package main
import "fmt"

func dfs(v int, graph [][]int, visited []bool) int{

    visited[v] = true
    count := 1

    for _,next := range graph[v] {
        if(!visited[next]){
            count += dfs(next,graph,visited)
        }
    }

    return count
}

func main() {

    var n, m int
    fmt.Scan(&n, &m)

    bombs := make([][]int, n)

    for i := 0; i < n; i++ {
        bombs[i] = make([]int, 3)
        fmt.Scan(&bombs[i][0], &bombs[i][1],&bombs[i][2])
    }

    graph := make([][]int, n)

    for i := 0; i < n; i++ {
        x1 := bombs[i][0]
        y1 := bombs[i][1]
        r := bombs[i][2]

        for j := 0; j < n; j++ {
            if i == j {
                continue
            }

            x2 := bombs[j][0]
            y2 := bombs[j][1]

            dx := int64(x1- x2)
            dy := int64(y1 - y2)

            dist2 := dx*dx + dy*dy

            r2 := int64(r) * int64(r)

            if(dist2 <= r2){
                graph[i] = append(graph[i], j)
            }
        }
    }

    ans :=0

    for i := 0; i < n; i++ {
        visited := make([]bool,n)
        cur := dfs(i, graph, visited)

        if(cur > ans){
            ans = cur
        }
    }

    fmt.Println(ans)

}
